python3 << 'EOF'
import pandas as pd
import numpy as np

df = pd.read_csv('/app/benchmark/data.csv')

def normalize_country(c):
    if c in ['USA', 'United States']:
        return 'United States'
    if c in ['China', 'PR China', "People's Republic of China"]:
        return 'China'
    if c == 'Republic of Korea':
        return 'South Korea'
    return c

df['country_clean'] = df['country'].apply(normalize_country)

# Country diversity index (Simpson's diversity)
print("=== Country concentration ===")
for yr in [2024, 2025, 2026]:
    sub = df[df['pub_year']==yr]
    counts = sub['country_clean'].value_counts()
    props = counts / counts.sum()
    diversity = 1 - (props**2).sum()
    print(f"{yr}: Simpson diversity = {diversity:.3f}, countries = {sub['country_clean'].nunique()}")

# Collaboration by research type and country
print("\n=== Mean authors by research type ===")
rt_map = {}
for rt in df['research_type'].unique():
    s = str(rt)
    if 'Preprint' in s and 'Journal Article' in s:
        rt_map[rt] = 'Preprint'
    elif s == 'Journal Article':
        rt_map[rt] = 'Journal Article'
    elif 'Systematic Review' in s:
        rt_map[rt] = 'Systematic Review'
    elif 'Review' in s and 'Journal Article' in s:
        rt_map[rt] = 'Review'
    elif 'Case Reports' in s:
        rt_map[rt] = 'Case Report'
    elif 'Randomized Controlled Trial' in s:
        rt_map[rt] = 'RCT'
    elif 'Journal Article' in s:
        rt_map[rt] = 'Journal Article (Other)'
    else:
        rt_map[rt] = 'Other'

df['research_type_simple'] = df['research_type'].map(rt_map)
print(df.groupby('research_type_simple')['authors_count'].agg(['median','mean','count']).sort_values('median', ascending=False))

# Abstract length by OA status
print("\n=== Abstract length by OA status ===")
print(df.groupby('open_access')['abstract_words'].agg(['median','mean']))

# DOI availability
print(f"\nDOI availability: {df['doi'].notna().sum()}/{len(df)} ({df['doi'].notna().mean():.1%})")
